//! macOS / BSD-flavour overrides + macOS-exclusive commands.
//!
//! Two purposes:
//!
//! 1. **Linux command overrides** — commands that exist on both
//!    Linux and macOS but emit BSD-style output that the Linux
//!    parser would mis-handle (`ifconfig`, `ps`, `df`, `netstat`,
//!    `lsof`, …). These shadow the Linux variant when the program
//!    name is dispatched.
//! 2. **macOS-exclusive commands** — `brew`, `defaults`, `diskutil`,
//!    `pmset`, `softwareupdate`, `pkgutil`, `kextstat`, etc.
//!
//! `pub mod` declarations are auto-generated by `build.rs` from the
//! directory contents.
//!
//! Cross-platform testing strategy:
//!   - Linux: unit tests + fixture-driven snapshots run during
//!     `cargo test`.
//!   - macOS: the project's mac-mini CI re-runs everything natively
//!     via `install/macos/`. Fixtures captured from real macOS runs
//!     are committed under `tests/fixtures/macos/` so unit tests
//!     don't need a Mac.

include!(concat!(env!("OUT_DIR"), "/cmd_macos_mods.rs"));

/// Content-shape dispatch — only includes shape-distinctive macOS
/// parsers (those that emit output recognisable without the program
/// name). Most macOS modules are passthrough or terse and are routed
/// by name only via [`crate::cmd::dispatch_named`].
pub fn dispatch(text: &str) -> Option<String> {
    if let Some(out) = ifconfig::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = launchctl::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = sw_vers::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = system_profiler::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = ps::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = netstat::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = df::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = diskutil::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = defaults::try_compact(text) {
        return Some(out);
    }
    None
}
